package com.clinica.backend.config;

import com.clinica.backend.security.JwtAuthFilter; import jakarta.servlet.http.HttpServletResponse; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.cors.*; import java.util.List;

@Configuration
public class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean SecurityFilterChain filterChain(HttpSecurity http,JwtAuthFilter jwt,@Value("${app.cors.allowed-origin}") String origin)throws Exception{return http.csrf(c->c.disable()).cors(c->c.configurationSource(r->{CorsConfiguration x=new CorsConfiguration();x.setAllowedOrigins(List.of(origin));x.setAllowedMethods(List.of("GET","POST","OPTIONS"));x.setAllowedHeaders(List.of("Authorization","Content-Type"));return x;})).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).exceptionHandling(e->e.authenticationEntryPoint((q,r,ex)->r.sendError(HttpServletResponse.SC_UNAUTHORIZED)).accessDeniedHandler((q,r,ex)->r.sendError(HttpServletResponse.SC_FORBIDDEN))).authorizeHttpRequests(a->a.requestMatchers(HttpMethod.OPTIONS,"/**").permitAll().requestMatchers("/api/auth/**","/api/doctors/public","/api/patients/public","/api/patients/exists/**").permitAll().requestMatchers("/api/appointments/my").hasRole("PATIENT").requestMatchers("/api/doctors/**","/api/patients/**","/api/appointments/**").hasRole("ADMIN").anyRequest().authenticated()).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build();}
}
